INSERT INTO GDX_PSY_INSTRUMENT_ITEM (ID_ITEM, ID_INSTRUMENT, ITEM_ORDER, STATEMENT_TEXT, RESPONSE_TYPE, REQUIRED) VALUES (100, 6, 18, 'How scared, fearful, or afraid did you feel?', 'LIKERT_0_4', 1); -- .sav column: RP18
INSERT INTO GDX_PSY_INSTRUMENT_ITEM (ID_ITEM, ID_INSTRUMENT, ITEM_ORDER, STATEMENT_TEXT, RESPONSE_TYPE, REQUIRED) VALUES (101, 6, 19, 'How serene, satisfied, and calm did you feel?', 'LIKERT_0_4', 1); -- .sav column: RP19
INSERT INTO GDX_PSY_INSTRUMENT_ITEM (ID_ITEM, ID_INSTRUMENT, ITEM_ORDER, STATEMENT_TEXT, RESPONSE_TYPE, REQUIRED) VALUES (102, 6, 20, 'How stressed, nervous, or overwhelmed did you feel?', 'LIKERT_0_4', 1); -- .sav column: RP20
INSERT INTO GDX_PSY_INSTRUMENT_ITEM (ID_ITEM, ID_INSTRUMENT, ITEM_ORDER, STATEMENT_TEXT, RESPONSE_TYPE, REQUIRED) VALUES (103, 7, 1, 'Rate how satisfied you feel with yourself, or in relation to your own person (Personal satisfaction, Diener, 1995).', 'LIKERT_5', 1); -- .sav column: SatPes
INSERT INTO GDX_PSY_INSTRUMENT_ITEM (ID_ITEM, ID_INSTRUMENT, ITEM_ORDER, STATEMENT_TEXT, RESPONSE_TYPE, REQUIRED) VALUES (104, 8, 1, 'Some people feel they have complete freedom of choice and control over their lives, while others feel that what they do has no effect on what happens to them. Please use the following scale to indicate the level of freedom of choice and control you feel you have over how your life unfolds (Perceived Control of Life, Inglehart, 1998).', 'LIKERT_5', 1); -- .sav column: CtrlVi
INSERT INTO GDX_PSY_INSTRUMENT_ITEM (ID_ITEM, ID_INSTRUMENT, ITEM_ORDER, STATEMENT_TEXT, RESPONSE_TYPE, REQUIRED) VALUES (105, 9, 1, 'My studies leave me emotionally exhausted.', 'LIKERT_5', 1); -- .sav column: ef1
INSERT INTO GDX_PSY_INSTRUMENT_ITEM (ID_ITEM, ID_INSTRUMENT, ITEM_ORDER, STATEMENT_TEXT, RESPONSE_TYPE, REQUIRED) VALUES (106, 9, 2, 'I feel "wiped out" at the end of a day at the Military Academy.', 'LIKERT_5', 1); -- .sav column: ef2
INSERT INTO GDX_PSY_INSTRUMENT_ITEM (ID_ITEM, ID_INSTRUMENT, ITEM_ORDER, STATEMENT_TEXT, RESPONSE_TYPE, REQUIRED) VALUES (107, 9, 3, 'I feel tired when I get up in the morning and think I have to face another day at the Military Academy.', 'LIKERT_5', 1); -- .sav column: ef3
INSERT INTO GDX_PSY_INSTRUMENT_ITEM (ID_ITEM, ID_INSTRUMENT, ITEM_ORDER, STATEMENT_TEXT, RESPONSE_TYPE, REQUIRED) VALUES (108, 9, 4, 'Studying or attending class leaves me tense.', 'LIKERT_5', 1); -- .sav column: ef4
INSERT INTO GDX_PSY_INSTRUMENT_ITEM (ID_ITEM, ID_INSTRUMENT, ITEM_ORDER, STATEMENT_TEXT, RESPONSE_TYPE, REQUIRED) VALUES (109, 9, 5, 'My studies leave me completely drained.', 'LIKERT_5', 1); -- .sav column: ef5
INSERT INTO GDX_PSY_INSTRUMENT_ITEM (ID_ITEM, ID_INSTRUMENT, ITEM_ORDER, STATEMENT_TEXT, RESPONSE_TYPE, REQUIRED) VALUES (110, 9, 6, 'I have been losing interest in my studies since I joined the Military Academy.', 'LIKERT_5', 1); -- .sav column: ef6
INSERT INTO GDX_PSY_INSTRUMENT_ITEM (ID_ITEM, ID_INSTRUMENT, ITEM_ORDER, STATEMENT_TEXT, RESPONSE_TYPE, REQUIRED) VALUES (111, 9, 7, 'I feel little enthusiasm about my studies.', 'LIKERT_5', 1); -- .sav column: ef7
INSERT INTO GDX_PSY_INSTRUMENT_ITEM (ID_ITEM, ID_INSTRUMENT, ITEM_ORDER, STATEMENT_TEXT, RESPONSE_TYPE, REQUIRED) VALUES (112, 9, 8, 'I feel increasingly cynical about the potential usefulness of my studies.', 'LIKERT_5', 1); -- .sav column: ef8
